xwikidoc.content:
{{include reference="ReleaseNotes.Code.Change.ChangeDisplayerVelocityMacros"/}}
{{velocity}} ## Inputs: ## - $changeItems ## - $displayEditLink ## A migration note is read by someone about to upgrade, who needs to know what it is about and what to do: each note ## is displayed as a section titled after it, holding its summary, and a link to the details its page holds when it ## has a description. #foreach ($item in $changeItems) #set ($changeDoc = $xwiki.getDocument($item)) #set ($changeObject = $changeDoc.getObject("ReleaseNotes.Code.Change.ChangeClass")) #generateDisplayEditLink($displayEditLink, $changeDoc) ## The title is emitted into a heading, which is wiki syntax, so it is escaped: left raw, a title carrying wiki ## syntax would have it rendered, macros included. #set ($title = $services.rendering.escape("$!changeObject.getValue('title')", 'xwiki/2.1')) ## The title of a note is optional, so a note is only given a section of its own when it has one: a heading holding ## no text at all would leave an empty section in the release note, and an empty entry in its table of contents. ## The edit link then follows the summary, the only thing that displays such a note. #if ($title != '') (% class="rn-migration-change" %) == $title${displayEditLinkMarkup}== #end ## Display the summary through the change document, so that its rich text is rendered in the context of that ## document rather than of this displayer, the way the note's own page renders it. The edit link of a note with no ## title reaches the summary line through a variable rather than through a directive closing that line: Velocity ## drops the newline ending a line that ends with a directive. #set ($summaryEditLinkMarkup = '') #if ($title == '') #set ($summaryEditLinkMarkup = $displayEditLinkMarkup) #end $changeDoc.display('summary', 'view', $changeObject)$summaryEditLinkMarkup
#if ("$!changeObject.getValue('description')" != '') [[${moreDetailsLabel}>>doc:$services.rendering.escape($services.model.serialize($changeDoc.documentReference, 'default'), 'xwiki/2.1')]] #end #end {{/velocity}}
